//! Closed MSBQ01: personal blood departure and pre-hand search.
//! Blood destinations use the existing finite departure queue, never a second interpreter.
use crate::{catalog,engine::RuleResult,model::*,rules::*,death_continuation::{PendingDeath,DeathDestination},society::SocietyDefinition};
use serde::{Serialize,Deserialize};
use std::collections::{BTreeMap,BTreeSet};
pub(crate) const ID:&str="MSBQ01";
pub(crate) const KEY:&str="msbq01-blood-departure";
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct BloodDeparture { pub host:SourceSnapshot, pub society:SourceSnapshot }
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
pub(crate) fn blood(c:&Card)->bool{let d=catalog::card(&c.definition);!c.face_down&&d.kind=="attachment"&&d.name=="鲜血"}
pub(crate) fn departed_definition(c:&Card)->&str{if c.definition==crate::jc028::FORM{crate::jc028::ID}else{&c.definition}}
pub(crate) fn definition()->Definition{with_abilities(vec![ability(KEY,"本方角色离场：将其鲜血附属封印于原龙之欢宴，替代入墓",Timing::Fast,vec![],vec![],vec![Op::MSBQ01Seal{attachment:None}],Some(Event::MSBQ01BloodLeft))])}
pub(crate) fn society()->SocietyDefinition{let mut card:catalog::CardDefinition=serde_json::from_value(serde_json::json!({"id":ID,"name":"龙之欢宴","subtitle":"王座逆党","kind":"society","type":"秘社/群体/吸血鬼","subtypes":["群体","吸血鬼"],"color":"蓝","society":"龙之欢宴","unique":true,"supported":false,"text":"构筑时只允许蓝、绿、中立，名称为鲜血的牌数量不限。抓起手牌前寻找一张鲜血封印于本秘社，然后洗牌。每当一个本方角色离场，若其上有鲜血附属，将该附属封印在本秘社上，而非置于墓地。"})).unwrap();card.abilities=definition().abilities.iter().map(|a|catalog::AbilitySummary{key:a.key.clone(),label:a.label.clone(),timing:"fast".into(),costs:a.costs.clone(),triggered:true}).collect();SocietyDefinition{card,subtitle:"王座逆党".into(),printed_cost:None,starting_hand:6,deck_constraints:vec![crate::society::SocietyDeckConstraint::BlueGreenNeutral],unresolved_abilities:BTreeMap::new()}}
pub(crate) fn related(a:&AbilitySpec)->bool{a.key.starts_with("msbq01-")||a.event==Some(Event::MSBQ01BloodLeft)||a.ops.iter().chain(a.modes.iter().flat_map(|m|&m.ops)).any(|o|matches!(o,Op::MSBQ01Seal{..}))}
pub(crate) fn declaration_id(d:&Declaration)->Option<&str>{if d.ability.key!=KEY{return None;}match d.ability.ops.as_slice(){[Op::MSBQ01Seal{attachment:Some(id)}]=>Some(id),_=>None}}
pub(crate) fn frame_id(f:&ResolutionFrame)->Option<&str>{if f.ability_key!=KEY{return None;}match f.steps.as_slice(){[Step{op:Op::MSBQ01Seal{attachment:Some(id)},..}]=>Some(id),_=>None}}
fn frame_related(f:&ResolutionFrame)->bool{f.ability_key.starts_with("msbq01-")||f.steps.iter().any(|s|matches!(s.op,Op::MSBQ01Seal{..}))}
pub(crate) fn validate_ability(id:&str,a:&AbilitySpec)->RuleResult<()>{let mut expected=definition().abilities.remove(0);if let [Op::MSBQ01Seal{attachment}]=a.ops.as_slice(){expected.ops=vec![Op::MSBQ01Seal{attachment:attachment.clone()}];}if id!=ID||!same(a,&expected){return Err("龙之欢宴只接受原本方离场封印程序".into());}Ok(())}
pub(crate) fn validate_definition(id:&str,d:&Definition)->RuleResult<()>{if(id==ID||d.abilities.iter().any(related))&&(id!=ID||!same(d,&definition())){return Err("龙之欢宴离场定义不可改写".into());}Ok(())}
impl Game {
 pub(crate) fn capture_msbq01_host(&self,id:&str)->Option<BloodDeparture>{let(r,c)=self.in_play(id)?;if c.face_down||catalog::card(&c.definition).kind!="character"{return None;}let seat=c.controller;let p=self.players.get(seat)?;let society=p.society_zone.card.as_ref()?;if p.eliminated||society.definition!=ID||society.face_down||society.owner!=seat||society.controller!=seat{return None;}let mut host=self.source_snapshot(c,r);host.source_region_instance=r.map(|r|self.regions[r].card.id.clone());Some(BloodDeparture{host,society:self.source_snapshot(society,None)})}
 pub(crate) fn hold_msbq01_attachment(&mut self,a:Attachment,b:BloodDeparture){let mut source=self.source_snapshot(&a.card,b.host.region);source.attachment_host_instance=Some(a.host_id);source.source_region_instance=b.host.source_region_instance.clone();let id=source.card.id.clone();let card=self.reset_zone_card(a.card);let mut ability=definition().abilities.remove(0);ability.ops=vec![Op::MSBQ01Seal{attachment:Some(id.clone())}];self.effects.push_back(Effect::Declare{declaration:Declaration{actor:b.society.card.controller,source:b.society.clone(),ability}});self.death_replacements.push(PendingDeath{declared_frame:None,blood:Some(b),turn:self.turn,source,transition_instance:card.id.clone(),card:Some(card),baseline_stack:self.stack.iter().map(|s|s.id.clone()).collect(),declaration_choice:None,destination:None});}
 pub(crate) fn validate_msbq01_attachment_source(&self,s:&SourceSnapshot)->RuleResult<()>{let c=&s.card;if !blood(c)||c.owner>=self.players.len()||c.controller>=self.players.len()||!self.mystic_instance_valid(&c.id)||s.attachment_host_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||s.play_source.is_some()||s.death_echo.is_some()||s.observed_death.is_some()||s.observed_exposure.is_some()||s.observed_mobility_grant.is_some()||self.batch3_physical_cards().any(|v|v.id==c.id){return Err("鲜血待定离场缺原附属身份或宿主".into());}self.mobility_immutable_identity(c)}
 fn msbq01_record(&self,id:&str,actor:usize,s:&SourceSnapshot)->RuleResult<&PendingDeath>{let d=self.death_replacements.iter().find(|d|d.source.card.id==id).ok_or("鲜血声明缺原挂起实体")?;let b=d.blood.as_ref().ok_or("鲜血声明不能引用角色死亡")?;if actor!=b.society.card.controller||!same(s,&b.society)||d.card.is_none()||d.destination.is_some(){return Err("鲜血声明更换原秘社、行动者或去向阶段".into());}Ok(d)}
 pub(crate) fn validate_msbq01_declaration(&self,d:&Declaration)->RuleResult<()>{if d.source.card.definition==ID||related(&d.ability){validate_ability(&d.source.card.definition,&d.ability)?;let id=declaration_id(d).ok_or("鲜血声明缺原附属实例")?;let held=self.msbq01_record(id,d.actor,&d.source)?;if held.declared_frame.is_some(){return Err("鲜血原声明已经入栈，不能重放".into());}}Ok(())}
 pub(crate) fn validate_msbq01_frame(&self,f:&ResolutionFrame)->RuleResult<()>{if !frame_related(f){if f.source.card.definition==ID&&!self.validated_cross_card_frame(f)?{return Err("龙之欢宴当前仅实现离场触发".into());}return Ok(());}let id=frame_id(f).ok_or("鲜血原帧缺唯一附属")?;let d=self.msbq01_record(id,f.actor,&f.source)?;if d.declared_frame.as_deref()!=Some(f.frame_id.as_str())||!self.mystic_instance_number(d.declaration_choice.as_deref().unwrap_or("")).zip(self.mystic_instance_number(&f.frame_id)).is_some_and(|(a,b)|a<b)||f.source.card.definition!=ID||f.cursor>1||f.cursor==0&&!matches!(f.guard,GuardState::Unchecked)||f.cursor==1&&!matches!(f.guard,GuardState::Accepted)||f.steps[0].context!=f.actor||!f.already_paid.is_empty()||!f.resource_payments.is_empty()||!f.targets.is_empty()||f.chosen_region.is_some(){return Err("鲜血原帧选择身份、费用或程序损坏".into());}Ok(())}
 pub(crate) fn record_msbq01_choice(&mut self)->RuleResult<()>{let Some((id,choice))=self.pending.as_ref().and_then(|p|if let ChoiceResolution::Declare{declaration:d,..}=&p.resolution{declaration_id(d).map(|id|(id.to_owned(),p.choice.id.clone()))}else{None})else{return Ok(());};let baseline=self.stack.iter().map(|s|s.id.clone()).collect();let d=self.death_replacements.iter_mut().find(|d|d.source.card.id==id).ok_or("鲜血选择缺原挂起")?;if d.declaration_choice.is_some(){return Err("鲜血替代不能重复声明".into());}d.declaration_choice=Some(choice);d.baseline_stack=baseline;Ok(())}
 pub(crate) fn resolve_msbq01_seal(&mut self,f:&ResolutionFrame)->RuleResult<()>{self.validate_msbq01_frame(f)?;if f.cursor!=1{return Err("鲜血封印未经过原守卫".into());}let id=frame_id(f).unwrap();let i=self.death_replacements.iter().position(|d|d.source.card.id==id).unwrap();let original=&self.death_replacements[i].blood.as_ref().unwrap().society.card;let seat=f.actor;let host=format!("society:p{seat}");if self.players[seat].eliminated||self.players[seat].society_zone.card.as_ref().is_none_or(|c|c.id!=original.id||c.definition!=ID||c.face_down)||!self.seal_host_valid(&host){return self.commit_pregrave_fallback(id);}let original_id=original.id.clone();let card=self.death_replacements[i].card.take().unwrap();self.seal_card_on_valid_host(card,seat,&host);let instance=self.sealed_cards.last().unwrap().card.id.clone();self.death_replacements[i].destination=Some(DeathDestination::Sealed{instance,host:original_id});Ok(())}
 pub(crate) fn append_msbq01_boundaries(&mut self,host_id:&str){let ids=self.death_replacements.iter().filter(|d|d.blood.as_ref().is_some_and(|b|b.host.card.id==host_id)&&!self.effects.iter().any(|e|matches!(e,Effect::DeathFinish{death_instance}if *death_instance==d.source.card.id))).map(|d|d.source.card.id.clone()).collect::<Vec<_>>();for death_instance in ids{self.effects.push_back(Effect::DeathFinish{death_instance});}}
 pub(crate) fn validate_msbq01_departure(&self,d:&PendingDeath)->RuleResult<()>{let b=d.blood.as_ref().ok_or("缺鲜血离场上下文")?;self.validate_msbq01_attachment_source(&d.source)?;let h=&b.host.card;let s=&b.society.card;if self.status!="playing"||d.turn!=self.turn||s.definition!=ID||s.face_down||s.owner>=self.players.len()||s.owner!=s.controller||h.controller!=s.controller||h.owner>=self.players.len()||h.face_down||catalog::card(&h.definition).kind!="character"||!self.mystic_instance_valid(&h.id)||!self.mystic_instance_valid(&s.id)||d.source.attachment_host_instance.as_ref()!=Some(&h.id)||d.source.region!=b.host.region||d.source.source_region_instance!=b.host.source_region_instance||b.society.region.is_some()||b.society.source_region_instance.is_some()||b.society.attachment_host_instance.is_some()||!self.mystic_instance_number(&d.source.card.id).zip(self.mystic_instance_number(&d.transition_instance)).is_some_and(|(a,b)|a<b)||self.effects.iter().filter(|e|matches!(e,Effect::DeathFinish{death_instance}if *death_instance==d.source.card.id)).count()!=1||d.baseline_stack.iter().collect::<BTreeSet<_>>().len()!=d.baseline_stack.len()||d.baseline_stack.iter().any(|id|!self.mystic_instance_number(id).zip(self.mystic_instance_number(d.declaration_choice.as_ref().unwrap_or(&d.transition_instance))).is_some_and(|(a,b)|a<b)){return Err("鲜血挂起来源、个人宿主或唯一去向边界损坏".into());}self.mobility_immutable_identity(h)?;self.mobility_immutable_identity(s)?;if b.host.region.is_some_and(|r|r>=self.regions.len())||b.host.region.is_some()&&b.host.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||b.society.play_source.is_some()||b.society.death_echo.is_some()||b.society.observed_death.is_some()||b.society.observed_exposure.is_some()||b.society.observed_mobility_grant.is_some()||d.declaration_choice.as_deref().is_some_and(|id|!self.mystic_instance_number(&d.transition_instance).zip(self.mystic_instance_number(id)).is_some_and(|(a,b)|a<b)){return Err("鲜血冻结位置、秘社观察或选择时序损坏".into());}if d.declared_frame.as_deref().is_some_and(|id|!self.mystic_instance_number(d.declaration_choice.as_deref().unwrap_or("")).zip(self.mystic_instance_number(id)).is_some_and(|(a,b)|a<b)){return Err("鲜血原响应实例必须晚于原选择".into());}let boundary=self.effects.iter().position(|e|matches!(e,Effect::DeathFinish{death_instance}if *death_instance==d.source.card.id)).unwrap();if self.effects.iter().skip(boundary+1).any(|e|matches!(e,Effect::Declare{declaration:x}if declaration_id(x)==Some(d.source.card.id.as_str()))){return Err("鲜血去向不能越过原未声明触发".into());}if let Some(DeathDestination::Grave{instance}|DeathDestination::Sealed{instance,..})=&d.destination{if self.batch3_physical_cards().any(|c|c.id==*instance&&(c.owner!=d.source.card.owner||c.definition!=departed_definition(&d.source.card))){return Err("鲜血最终实体改换拥有者或牌面".into());}}
 match(&d.card,&d.destination){(Some(c),None)=>{let mut g=self.clone();let mut expected=g.reset_zone_card(d.source.card.clone());expected.id=d.transition_instance.clone();if !same(c,&expected)||self.batch3_physical_cards().filter(|v|v.id==c.id).count()!=1{return Err("鲜血挂起牌不是原实体完整重置后的唯一牌".into());}},(None,Some(DeathDestination::Grave{instance}))=>{if instance!=&d.transition_instance{return Err("鲜血回退墓地改换实例".into());}},(None,Some(DeathDestination::Sealed{instance,host}))=>{if host!=&s.id||!self.mystic_instance_number(&d.transition_instance).zip(self.mystic_instance_number(instance)).is_some_and(|(a,b)|a<b){return Err("鲜血封印改变了原秘社或换号顺序".into());}},(None,Some(DeathDestination::Removed))if self.players[d.source.card.owner].eliminated=>{},_=>return Err("鲜血持有牌和最终去向阶段必须互斥".into())}
 let mut live=0;for e in &self.effects{if let Effect::Declare{declaration:x}=e{if declaration_id(x)==Some(d.source.card.id.as_str()){self.validate_msbq01_declaration(x)?;if d.declaration_choice.is_some(){return Err("鲜血原声明重放".into());}live+=1;}}}for i in &self.stack{if let Some(f)=&i.frame{if frame_id(f)==Some(d.source.card.id.as_str()){self.validate_msbq01_frame(f)?;live+=1;}}}if let Some(p)=&self.pending{if let ChoiceResolution::Declare{declaration:x,..}=&p.resolution{if declaration_id(x)==Some(d.source.card.id.as_str()){if d.declaration_choice.as_deref()!=Some(&p.choice.id){return Err("鲜血原待选身份改变".into());}live+=1;}}}if live>1||d.destination.is_some()&&live!=0||d.card.is_some()&&live==0&&!self.death_boundary_waits(&d.source.card.id)&&!self.players[s.controller].eliminated{return Err("鲜血离场触发缺失或被重复承载".into());}Ok(())}
 pub(crate) fn validate_msbq01_state(&self)->RuleResult<()>{self.validate_msbq01_opening()?;for e in &self.effects{match e{Effect::Declare{declaration:d}=>self.validate_msbq01_declaration(d)?,Effect::Frame{frame:f}if frame_related(f)=>return Err("鲜血单步不应留下游离续帧".into()),_=>()}}for i in &self.stack{if let Some(d)=self.death_replacements.iter().find(|d|d.blood.is_some()&&d.declared_frame.as_deref()==Some(i.id.as_str())){if i.frame.as_ref().is_none_or(|f|frame_id(f)!=Some(d.source.card.id.as_str())){return Err("鲜血实际响应载体丢失或换源".into());}}if let Some(f)=&i.frame{self.validate_msbq01_frame(f)?;if frame_related(f)&&(i.id!=f.frame_id||i.controller!=f.actor||i.card.is_some()||i.target.is_some()||i.deploy_region.is_some()||i.reveal||f.cursor!=0){return Err("鲜血触发响应外壳损坏".into());}}}if let Some(p)=&self.pending{match &p.resolution{ChoiceResolution::Declare{declaration:d,stage}if d.source.card.definition==ID||related(&d.ability)=>{self.validate_msbq01_declaration(d)?;let expected=Choice{id:p.choice.id.clone(),kind:"trigger".into(),title:format!("{}：{}",crate::batch3_trap::source_label(&d.source),d.ability.label),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(d.actor),options:vec![ChoiceOption{id:"accept".into(),label:"发动触发能力".into(),card:None}],preview_cards:vec![],min:Some(0),max:Some(1),amount:None,allow_decline:Some(true)};if p.seat!=d.actor||!matches!(stage,DeclareChoice::Accept)||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice,&expected){return Err("鲜血原可选触发待选损坏".into());}},ChoiceResolution::Frame{frame:f,..}if frame_related(f)=>return Err("鲜血封印没有额外待选".into()),_=>()}}Ok(())}
 pub(crate) fn cancel_msbq01_owner(&mut self,owner:usize){let ids=self.death_replacements.iter().filter(|d|d.blood.is_some()&&d.source.card.owner==owner).map(|d|d.source.card.id.clone()).collect::<BTreeSet<_>>();self.effects.retain(|e|!matches!(e,Effect::Declare{declaration:d}if declaration_id(d).is_some_and(|id|ids.contains(id))));self.stack.retain(|i|i.frame.as_ref().is_none_or(|f|frame_id(f).is_none_or(|id|!ids.contains(id))));if self.pending.as_ref().is_some_and(|p|matches!(&p.resolution,ChoiceResolution::Declare{declaration:d,..}if declaration_id(d).is_some_and(|id|ids.contains(id)))){self.pending=None;}}
}

impl Game{pub(crate) fn validate_msbq01_wait(&self,w:&crate::death_continuation::DeathWait)->RuleResult<()>{if !blood(&w.source.card){if w.blood.is_some(){return Err("非鲜血等待不能夹带附属上下文".into());}return Ok(());}let b=w.blood.as_ref().ok_or("鲜血原调用方丢失宿主和秘社绑定")?;let h=&b.host.card;let s=&b.society.card;if s.definition!=ID||s.face_down||s.controller>=self.players.len()||s.owner!=s.controller||h.controller!=s.controller||h.owner>=self.players.len()||h.face_down||catalog::card(&h.definition).kind!="character"||w.source.attachment_host_instance.as_ref()!=Some(&h.id)||w.source.region!=b.host.region||w.source.source_region_instance!=b.host.source_region_instance||!self.mystic_instance_valid(&h.id)||!self.mystic_instance_valid(&s.id){return Err("鲜血等待更换本方宿主或原秘社".into());}self.mobility_immutable_identity(h)?;self.mobility_immutable_identity(s)?;if let Some(DeathDestination::Sealed{host,..})=&w.destination{if *host!=s.id{return Err("鲜血等待去向更换原秘社".into());}}if let Some(d)=self.death_replacements.iter().find(|d|d.source.card.id==w.source.card.id){if !same(&d.blood,&w.blood){return Err("鲜血等待与实际挂起来源不同".into());}}Ok(())}}

impl Game{pub(crate) fn record_msbq01_frame(&mut self,f:&ResolutionFrame){if let Some(id)=frame_id(f){if let Some(d)=self.death_replacements.iter_mut().find(|d|d.source.card.id==id&&d.blood.is_some()){debug_assert!(d.declared_frame.is_none());d.declared_frame=Some(f.frame_id.clone());}}}}

const OPEN:&str="msbq01-opening";
const DONE:&str="msbq01-opening-done";
const OPEN_TITLE:&str="龙之欢宴：从牌库寻找一张鲜血并封印";
impl Game {
 fn msbq01_open_live(&self,seat:usize)->bool{self.players.get(seat).is_some_and(|p|!p.eliminated&&p.society_zone.card.as_ref().is_some_and(|c|c.definition==ID&&!c.face_down&&c.owner==seat&&c.controller==seat))}
 pub(crate) fn msbq01_defer_hand(&mut self,seat:usize)->bool{if !self.msbq01_open_live(seat){return false;}self.players[seat].society_zone.used_once_per_game.insert(OPEN.into());self.effects.push_back(Effect::MSBQ01Opening{seat});true}
 fn msbq01_open_valid(&self,seat:usize)->RuleResult<()>{if !self.msbq01_open_live(seat)||self.turn!=1||!self.players[seat].hand.is_empty()||!self.players[seat].society_zone.used_once_per_game.contains(OPEN)||self.players[seat].society_zone.used_once_per_game.contains(DONE){return Err("龙之欢宴缺原起手前授权".into());}Ok(())}
 fn msbq01_open_options(&self,seat:usize)->Vec<ChoiceOption>{self.players[seat].deck.iter().filter(|c|catalog::card(&c.definition).name=="鲜血").map(|c|self.option(c,seat,None,None)).collect()}
 pub(crate) fn msbq01_open(&mut self,seat:usize)->RuleResult<()>{self.msbq01_open_valid(seat)?;let options=self.msbq01_open_options(seat);if options.is_empty(){return self.msbq01_open_finish(seat,&[]);}self.choice(seat,OPEN,OPEN_TITLE.into(),options,1,1,None,ChoiceResolution::MSBQ01Opening{seat});Ok(())}
 pub(crate) fn msbq01_open_finish(&mut self,seat:usize,ids:&[String])->RuleResult<()>{self.msbq01_open_valid(seat)?;let options=self.msbq01_open_options(seat);if ids.len()!=usize::from(!options.is_empty())||ids.iter().any(|id|!options.iter().any(|o|&o.id==id)){return Err("须选择本人牌库一张鲜血；无合法牌才零张".into());}if let Some(id)=ids.first(){let i=self.players[seat].deck.iter().position(|c|&c.id==id).unwrap();let c=self.players[seat].deck.remove(i);self.seal_card_on_valid_host(c,seat,&format!("society:p{seat}"));}let mut deck=std::mem::take(&mut self.players[seat].deck);self.shuffle(&mut deck);self.players[seat].deck=deck;self.players[seat].society_zone.used_once_per_game.insert(DONE.into());self.draw(seat,6)}
 fn validate_msbq01_opening(&self)->RuleResult<()>{let mut openings=BTreeSet::new();for e in &self.effects{if let Effect::MSBQ01Opening{seat}=e{self.msbq01_open_valid(*seat)?;if !openings.insert(*seat){return Err("重复鲜血起手续体".into());}}}if let Some(p)=&self.pending{if let ChoiceResolution::MSBQ01Opening{seat}=&p.resolution{self.msbq01_open_valid(*seat)?;let options=self.msbq01_open_options(*seat);let expected=Choice{id:p.choice.id.clone(),kind:OPEN.into(),title:OPEN_TITLE.into(),description:"选择符合数量限制的选项，然后确认。".into(),player_id:player_id(*seat),options,preview_cards:vec![],min:Some(1),max:Some(1),amount:None,allow_decline:Some(false)};if !openings.insert(*seat)||p.seat!=*seat||expected.options.is_empty()||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice,&expected){return Err("鲜血起手选择损坏".into());}}}for p in &self.players{let marks=&p.society_zone.used_once_per_game;if marks.contains(DONE)&&!marks.contains(OPEN)||marks.contains(OPEN)&&!marks.contains(DONE)&&!openings.contains(&p.seat){return Err("鲜血起手前续体丢失".into());}}Ok(())}
}
